arguments.new_string:
# manifest can be a list, a dict with campaigns, a dict with regions, or a single campaign dict; normalise
if isinstance(manifest, dict):
    if isinstance(manifest.get('campaigns'), list):
        campaigns_list = manifest['campaigns']
    elif isinstance(manifest.get('regions'), list):
        campaigns_list = []
        for region in manifest['regions']:
            if isinstance(region, dict) and isinstance(region.get('campaigns'), list):
                campaigns_list.extend(region['campaigns'])
    else:
        campaigns_list = [manifest]
else:
    campaigns_list = manifest
